function myFunction() {
function doGet(e) {
  const filename = e.parameter.filename;
  if (!filename) return ContentService.createTextOutput("Missing filename parameter");

  const file = DriveApp.getFilesByName(filename);
  if (!file.hasNext()) return ContentService.createTextOutput("File not found");

  const foundFile = file.next();
  const blob = foundFile.getBlob();

  return ContentService
    .createBinaryOutput(blob.getBytes())
    .setMimeType(blob.getContentType())
    .downloadAsFile(foundFile.getName());
}

/**
 * HTTP POST — загрузка нового файла
 * Body должен быть JSON: { "filename": "имя.txt", "content": "текст файла" }
 */
function doPost(e) {
  const data = JSON.parse(e.postData.contents);
  const filename = data.filename || "default.txt";
  const content = data.content || "";

  const blob = Utilities.newBlob(content, "text/plain", filename);
  const file = DriveApp.createFile(blob);

  return ContentService.createTextOutput(
    JSON.stringify({ status: "success", fileId: file.getId(), name: file.getName() })
  ).setMimeType(ContentService.MimeType.JSON);
}

}
